-- >>>>>>>>>>>>>>>>>>>> 20261102000001_daily_output.sql

-- =============================================================================
-- Daily output: a site engineer picks a schedule task and records what was done that day — quantity (units
-- tasks) or percent / status (other EV methods), manpower, equipment, delay cause and remarks.
-- One entry =
--   * a task progress report (task_progress, cumulative to date → EVM / verification), and
--   * a line in that day's site diary (diary_activities); the diary is opened as a draft when missing.
-- Safe to run again (if not exists / drop if exists).
-- Quantities are entered as TODAY's output; the to-date figure is the task's latest reported (or verified)
-- quantity plus today's.
-- =============================================================================

create table if not exists public.diary_activities (
  id                uuid primary key,
  diary_id          uuid not null references public.site_diaries (id),
  project_id        uuid not null references public.projects (id),
  task_id           uuid not null references public.schedule_tasks (id),
  task_progress_id  uuid references public.task_progress (id),
  activity_date     date not null,
  method            text not null,
  -- units tasks: [{boq_item_id, item_no, unit, qty_today, qty_to_date}]
  output            jsonb not null default '[]'::jsonb,
  pct_to_date       numeric(5,2),
  headcount         int check (headcount >= 0),
  labour_hours      numeric(6,1) check (labour_hours >= 0),
  equipment         text,
  delay_cause       text,
  remarks           text,
  after_signoff     boolean not null default false,  -- added after the diary was signed (also written as an addendum)
  created_by        uuid not null references public.profiles (id),
  device_id         uuid,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz
);

create index if not exists diary_activities_diary_idx on public.diary_activities (diary_id);
create index if not exists diary_activities_day_idx on public.diary_activities (project_id, activity_date);
create index if not exists diary_activities_task_idx on public.diary_activities (task_id);
create index if not exists diary_activities_updated_at_idx on public.diary_activities (updated_at);
drop trigger if exists touch_updated_at on public.diary_activities;
create trigger touch_updated_at before update on public.diary_activities
  for each row execute function app.touch_updated_at();
drop trigger if exists audit on public.diary_activities;
create trigger audit after insert or update or delete on public.diary_activities
  for each row execute function app.audit();
drop trigger if exists no_delete on public.diary_activities;
create trigger no_delete before delete on public.diary_activities
  for each row execute function app.block_mutation();
alter table public.diary_activities enable row level security;
drop policy if exists member_read on public.diary_activities;
create policy member_read on public.diary_activities for select to authenticated using (app.is_member(project_id));

create or replace function public.report_daily_output(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p);
  v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid());
  v_tp uuid := gen_random_uuid();
  v_today date := app.eat_date(now());
  v_date date := coalesce((p ->> 'date')::date, v_today);
  v_block uuid := nullif(p ->> 'block_id', '')::uuid;
  v_remarks text := nullif(trim(p ->> 'remarks'), '');
  t public.schedule_tasks;
  d public.site_diaries;
  x record;
  v_inner jsonb;
  v_qty jsonb := '[]'::jsonb;
  v_out jsonb := '[]'::jsonb;
  v_sum numeric := 0;
  v_res jsonb;
  v_text text;
begin
  if v_seen is not null then return v_seen; end if;
  select * into t from public.schedule_tasks where id = (p ->> 'task_id')::uuid;
  if not found then raise exception 'Choose an activity from the schedule'; end if;
  perform app.require_member(t.project_id);
  perform app.require_role('site_engineer','office_engineer','coordinator','manager','admin');
  if v_date > v_today then raise exception 'Daily output cannot be dated in the future (%)', v_date; end if;
  if v_block is not null and not exists (select 1 from public.blocks where id = v_block and project_id = t.project_id) then
    raise exception 'Block does not belong to this project';
  end if;
  if (p ->> 'headcount')::numeric < 0 or (p ->> 'labour_hours')::numeric < 0 then raise exception 'Manpower cannot be negative'; end if;

  v_inner := jsonb_build_object('id', v_tp, 'task_id', t.id, 'status_date', v_date)
    || jsonb_strip_nulls(jsonb_build_object(
         'actual_start', nullif(p ->> 'actual_start', ''), 'actual_finish', nullif(p ->> 'actual_finish', ''),
         'remaining_days', p -> 'remaining_days', 'delay_cause', nullif(p ->> 'delay_cause', ''), 'remarks', v_remarks));

  if t.ev_method = 'units' then
    -- every linked item is sent (unchanged ones keep their to-date) so the task percent is computed on all of them
    for x in
      select l.boq_item_id, b.item_no, b.unit, greatest(l.reported_qty, l.verified_qty) as cur,
             coalesce((select (o ->> 'qty_today')::numeric from jsonb_array_elements(coalesce(p -> 'output', '[]'::jsonb)) o
                        where (o ->> 'boq_item_id')::uuid = l.boq_item_id limit 1), 0) as today
        from public.task_boq_links l join public.boq_items b on b.id = l.boq_item_id
       where l.task_id = t.id and l.deleted_at is null
       order by b.item_no
    loop
      if x.today < 0 then raise exception 'Today''s quantity for % cannot be negative', x.item_no; end if;
      v_sum := v_sum + x.today;
      v_qty := v_qty || jsonb_build_object('boq_item_id', x.boq_item_id, 'qty_to_date', x.cur + x.today);
      if x.today > 0 then
        v_out := v_out || jsonb_build_object('boq_item_id', x.boq_item_id, 'item_no', x.item_no, 'unit', x.unit,
                                             'qty_today', x.today, 'qty_to_date', x.cur + x.today);
      end if;
    end loop;
    if jsonb_array_length(v_qty) = 0 then
      raise exception 'Activity "%" has no BoQ items linked — ask the office engineer to create or link the BoQ', t.name;
    end if;
    if v_sum = 0 and nullif(p ->> 'actual_finish', '') is null then raise exception 'Enter the quantity done today'; end if;
    v_inner := v_inner || jsonb_build_object('qty', v_qty);
  elsif t.ev_method = 'steps' then
    v_inner := v_inner || jsonb_build_object('steps', p -> 'steps');
  else
    v_inner := v_inner || jsonb_build_object('pct_complete', p -> 'pct_complete');
  end if;

  v_res := public.report_task_progress(v_inner);

  select * into d from public.site_diaries
   where project_id = t.project_id and block_id is not distinct from v_block and diary_date = v_date;
  if not found then
    if nullif(p ->> 'diary_number', '') is null then raise exception 'diary_number is required to open the site diary for %', v_date; end if;
    insert into public.site_diaries (id, project_id, number, diary_date, block_id, created_by, device_id)
    values (gen_random_uuid(), t.project_id, p ->> 'diary_number', v_date, v_block, auth.uid(), app.device_id())
    on conflict do nothing;
    select * into d from public.site_diaries
     where project_id = t.project_id and block_id is not distinct from v_block and diary_date = v_date;
    if not found then raise exception 'Could not open the site diary for % — try again', v_date; end if;
  end if;

  insert into public.diary_activities (id, diary_id, project_id, task_id, task_progress_id, activity_date, method, output,
    pct_to_date, headcount, labour_hours, equipment, delay_cause, remarks, after_signoff, created_by, device_id)
  values (v_id, d.id, t.project_id, t.id, v_tp, v_date, t.ev_method, v_out, (v_res ->> 'pct_complete')::numeric,
    (p ->> 'headcount')::int, (p ->> 'labour_hours')::numeric, nullif(trim(p ->> 'equipment'), ''),
    nullif(p ->> 'delay_cause', ''), v_remarks, d.status = 'signed', auth.uid(), app.device_id());

  if d.status = 'signed' then
    select string_agg((o ->> 'qty_today') || ' ' || (o ->> 'unit'), ', ') into v_text from jsonb_array_elements(v_out) o;
    insert into public.diary_addenda (id, diary_id, project_id, text, created_by)
    values (gen_random_uuid(), d.id, t.project_id,
      'Daily output added after sign-off: ' || coalesce(t.wbs || ' ', '') || t.name || ' — '
        || coalesce(v_text, round((v_res ->> 'pct_complete')::numeric, 1) || '%') || coalesce(' (' || v_remarks || ')', ''),
      auth.uid());
  end if;

  return app.op_done(p, 'report_daily_output', jsonb_build_object('ok', true, 'id', v_id, 'task_progress_id', v_tp,
    'diary_id', d.id, 'diary_number', d.number, 'diary_status', d.status, 'status_date', v_res -> 'status_date',
    'pct_complete', v_res -> 'pct_complete', 'output', v_out, 'rolled_to_next_period', v_res -> 'rolled_to_next_period'));
end $$;


-- >>>>>>>>>>>>>>>>>>>> 20261102000002_lookahead_needs_pushdown.sql

-- v_lookahead_material_needs filtered on c.plan_id (an output of app.la_material_calc), so `where plan_id = …`
-- could not be pushed down and the calculation ran for EVERY look-ahead plan before filtering — minutes per
-- request once a few plans exist. Taking plan_id / project_id from lookahead_plans lets Postgres restrict the
-- lateral call to the requested plan. Same columns, same order.
create or replace view public.v_lookahead_material_needs with (security_invoker = true) as
select pl.id as plan_id, pl.project_id, pl.period_label, c.item_id, i.name as item_name, i.window_role, i.planned_start, i.planned_finish,
       i.responsible_id, c.material_spec_id, sp.label, sp.category, sp.uom, c.element_ids,
       c.total_need, c.remaining, c.window_need, c.weekly_need, c.need_by, c.lead_time_days, c.safety_days, c.order_by, c.pack_size,
       c.ati_before, c.from_stock, c.from_po, c.from_po_late, c.from_procurement, c.from_pending_pr,
       c.short_firm, c.to_order, c.suggested_qty, c.raise_pr_now, c.late_order, c.arrives_late, c.suggest_sur,
       c.next_po_eta, c.late_po_eta, c.po_numbers, c.mr_numbers,
       case when c.late_order then 'late_order' when c.raise_pr_now then 'raise_pr_now' when c.to_order > 0 then 'to_order'
            when c.arrives_late then 'arrives_late' when c.from_procurement + c.from_pending_pr > 0 then 'in_procurement'
            else 'covered' end as need_status
from public.lookahead_plans pl
cross join lateral app.la_material_calc(pl.id) c
join public.lookahead_items i on i.id = c.item_id
join public.v_specs sp on sp.id = c.material_spec_id;


-- >>>>>>>>>>>>>>>>>>>> 20261102000021_e2e_purchase_fixes.sql

-- =============================================================================
-- Purchase-flow fixes found in the end-to-end run (project TWR)
--
-- RFQ award had no owner: procurement records the quotations, but awarding is a management
-- step (rfq.award = coordinator / manager / admin with price access) and nothing told management
-- an RFQ was ready — it sat unawarded. Now:
--   * inbox item 'rfq_award' (v_my_approvals) once the RFQ has its minimum quotations or was
--     closed for quotes with at least one, until it is awarded or cancelled;
--   * management is notified when the minimum is reached and when the RFQ is closed for quotes.
-- =============================================================================

-- (guarded so the upgrade script can be run again)
do $$
begin
  if to_regprocedure('app.approvals_for_pre_purchase(uuid)') is null then
    alter function app.approvals_for(uuid) rename to approvals_for_pre_purchase;
  end if;
end $$;

create or replace function app.approvals_for(p_user uuid)
returns table (kind text, entity_type text, entity_id uuid, project_id uuid, number text, title text, status text,
               requested_by uuid, requested_at timestamptz, is_urgent boolean, actions text[], age_hours numeric)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare v_role text; v_prices boolean;
begin
  return query select * from app.approvals_for_pre_purchase(p_user);   -- also checks the caller may read p_user's inbox
  select pr.role::text into v_role from public.profiles pr where pr.id = p_user and pr.is_active;
  if v_role is null or v_role not in ('coordinator','manager','admin') then return; end if;
  v_prices := v_role = 'admin' or v_role = any (coalesce((select s.price_roles::text[] from public.app_settings s where s.id = 1), '{}'));
  if not v_prices then return; end if;
  return query
  with mem as (
    select pm.project_id as pid from public.project_members pm where pm.user_id = p_user
    union select pj.id from public.projects pj where v_role = 'admin'),
  rq as (
    select q.*, (select count(*) from public.quotations qt where qt.rfq_id = q.id and qt.status <> 'withdrawn') as n_quotes
    from public.rfqs q
    where q.project_id in (select pid from mem) and q.status in ('sent','closed')
      and not exists (select 1 from public.rfq_awards aw where aw.rfq_id = q.id))
  select 'rfq_award'::text, 'rfq'::text, rq.id, rq.project_id, rq.number,
         'Award ' || rq.title || ' (' || rq.n_quotes || ' of ' || rq.min_quotes || ' quotations)',
         rq.status, rq.created_by, coalesce(rq.closed_at, rq.sent_at, rq.created_at),
         rq.required_by is not null and rq.required_by <= app.local_date(now()), array['open'],
         round((extract(epoch from now() - coalesce(rq.closed_at, rq.sent_at, rq.created_at)) / 3600)::numeric, 1)
  from rq
  where rq.n_quotes >= rq.min_quotes or (rq.status = 'closed' and rq.n_quotes > 0);
end $$;

-- v_my_approvals is a union with the look-ahead items (20261030000004); re-create it so it calls the new function.
do $$
begin
  execute 'create or replace view public.v_my_approvals as
           select * from app.approvals_for(auth.uid())
           union all
           select * from app.lookahead_approvals_for(auth.uid())';
exception when undefined_function then
  execute 'create or replace view public.v_my_approvals as select * from app.approvals_for(auth.uid())';
end $$;
grant select on public.v_my_approvals to authenticated;

create or replace function app.notify_rfq_ready(p_rfq uuid, p_why text) returns void
language plpgsql security definer set search_path = public as $$
declare q public.rfqs; v_n int;
begin
  select * into q from public.rfqs where id = p_rfq;
  if not found or exists (select 1 from public.rfq_awards where rfq_id = q.id) then return; end if;
  select count(*) into v_n from public.quotations where rfq_id = q.id and status <> 'withdrawn';
  perform app.notify_roles(q.project_id, '{coordinator,manager}', 'RFQ ' || q.number || ' ready to award',
    q.title || ' — ' || v_n || ' quotation' || case when v_n = 1 then '' else 's' end || ' ' || p_why, 'rfq', q.id);
end $$;

create or replace function app.trg_quotation_ready() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_min int; v_n int;
begin
  select min_quotes into v_min from public.rfqs where id = new.rfq_id;
  select count(*) into v_n from public.quotations where rfq_id = new.rfq_id and status <> 'withdrawn';
  if v_n = v_min then perform app.notify_rfq_ready(new.rfq_id, 'received (minimum reached)'); end if;
  return null;
end $$;
drop trigger if exists notify_ready on public.quotations;
create trigger notify_ready after insert on public.quotations
  for each row execute function app.trg_quotation_ready();

create or replace function app.trg_rfq_closed_ready() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'closed' and old.status is distinct from 'closed' then perform app.notify_rfq_ready(new.id, '— closed for quotes'); end if;
  return null;
end $$;
drop trigger if exists notify_ready on public.rfqs;
create trigger notify_ready after update of status on public.rfqs
  for each row execute function app.trg_rfq_closed_ready();

revoke execute on function app.notify_rfq_ready(uuid, text) from public;

-- -----------------------------------------------------------------------------
-- Draft POs created by the award (award_rfq, run by management) were authored by the awarder, so the buyer
-- who ran the RFQ could not complete or submit them ("Only the author can edit this purchase order") and the
-- awarder could not approve them ("your own purchase order"). The buyer (RFQ author, procurement) is the PO
-- author; who awarded stays on rfq_awards / po_events.
-- -----------------------------------------------------------------------------
create or replace function app.trg_po_author_from_rfq() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_buyer uuid;
begin
  if new.rfq_id is null or app.has_role('procurement') then return new; end if;
  select q.created_by into v_buyer from public.rfqs q join public.profiles pr on pr.id = q.created_by
   where q.id = new.rfq_id and pr.role = 'procurement' and pr.is_active;
  if v_buyer is not null then new.created_by := v_buyer; end if;
  return new;
end $$;
drop trigger if exists author_from_rfq on public.purchase_orders;
create trigger author_from_rfq before insert on public.purchase_orders
  for each row execute function app.trg_po_author_from_rfq();

update public.purchase_orders po set created_by = q.created_by
  from public.rfqs q join public.profiles pr on pr.id = q.created_by and pr.role = 'procurement' and pr.is_active
 where po.rfq_id = q.id and po.status in ('draft','rejected') and po.created_by <> q.created_by
   and exists (select 1 from public.profiles c where c.id = po.created_by and c.role in ('coordinator','manager','admin'));

-- -----------------------------------------------------------------------------
-- PR tracker after a PO short-close: ordered_qty counted the closed PO line at its full quantity, so the
-- undelivered balance (e.g. 600 kg of 24 t) never showed as "to source" again and the PR stayed partially
-- received with nobody prompted. A closed PO / PO line now counts what was accepted on it.
-- -----------------------------------------------------------------------------
create or replace view public.v_pr_tracker with (security_invoker = true) as
select ml.id as mr_line_id, ml.mr_id, r.number, r.project_id, r.status, r.priority, r.source_mr_id, ml.source_mr_line_id,
       ml.line_no, ml.material_spec_id, sp.label, sp.uom, ml.qty as requested_qty, ml.reviewed_qty, ml.approved_qty, ml.line_status,
       coalesce((select sum(rl.qty) from public.rfq_lines rl join public.rfqs q on q.id = rl.rfq_id
                  where rl.mr_line_id = ml.id and rl.deleted_at is null and q.status <> 'cancelled'), 0) as on_rfq_qty,
       coalesce((select sum(case when po.status = 'closed' or pl.closed then pl.qty_accepted else pl.qty end)
                  from public.po_lines pl join public.purchase_orders po on po.id = pl.po_id
                  where pl.mr_line_id = ml.id and pl.deleted_at is null
                    and po.status in ('sent','partially_received','received','closed')), 0) as ordered_qty,
       (select min(coalesce(po.eta, pl.expected_date, po.expected_date)) from public.po_lines pl
          join public.purchase_orders po on po.id = pl.po_id
         where pl.mr_line_id = ml.id and pl.deleted_at is null and not pl.closed
           and po.status in ('approved','sent','partially_received')) as eta,
       (select min(dn.expected_date) from public.delivery_notices dn
          where dn.status in ('notified','acknowledged','reschedule_requested','arrived')
            and dn.po_id in (select pl.po_id from public.po_lines pl where pl.mr_line_id = ml.id and pl.deleted_at is null)) as notice_date,
       ml.qty_received as received_qty,
       case when ml.line_status = 'open' then greatest(coalesce(ml.approved_qty, 0) - ml.qty_received, 0) else 0 end as outstanding_qty
from public.mr_lines ml
join public.material_requests r on r.id = ml.mr_id and r.request_type = 'purchase'
join public.v_specs sp on sp.id = ml.material_spec_id
where ml.deleted_at is null;
grant select on public.v_pr_tracker to authenticated;


-- >>>>>>>>>>>>>>>>>>>> 20261102000022_e2e_siteuse_fixes.sql

-- =============================================================================
-- Site-use / store workflow fixes found in the end-to-end run on the real 2B+G+15 schedule.
-- 1. app.la_material_calc: an element linked to several tasks (drill, rebar, pour of one pile group) put its
--    whole take-off on every one of them, so the look-ahead tripled the rebar need and gave the stock to the
--    drilling task. A take-off tagged with a BoQ item now only counts for tasks delivering that item (or tasks
--    without BoQ links).
-- 2. create_sur_from_lookahead: "Block is required" for schedule items without an element — the block now falls
--    back to the task's linked elements, the task's block, or the project's only block.
-- =============================================================================

create or replace function app.la_material_calc(p_plan uuid) returns setof app.la_material_row
language plpgsql stable set search_path = public as $$
declare
  v_today date := app.la_today();
  v_project uuid; v_start date; v_end date; v_hor date;
  v_items uuid[];
  d record;
  r app.la_material_row;
  v_spec uuid := null;
  v_ati numeric; v_proc numeric; v_pend numeric; v_mrs text[];
  v_po_eta date[]; v_po_qty numeric[]; v_po_no text[];
  v_rem numeric; v_take numeric; v_share numeric; k int; v_pos text[];
begin
  select project_id, period_start, period_end, horizon_end into v_project, v_start, v_end, v_hor
    from public.lookahead_plans where id = p_plan;
  if v_project is null then return; end if;
  select coalesce(array_agg(id), '{}') into v_items from public.lookahead_items where plan_id = p_plan;

  for d in
    with it as materialized (
      select i.id, i.schedule_task_id, i.sort_key, x.s, x.f, x.pct,
             app.la_wd(v_project, greatest(x.s, v_today), x.f) as den,
             app.la_wd(v_project, greatest(x.s, v_today, v_start), least(x.f, v_hor)) as num,
             coalesce((select jsonb_object_agg(w.week_start::text,
                         app.la_wd(v_project, greatest(x.s, v_today, w.week_start), least(x.f, w.week_end)))
                       from public.lookahead_weeks w where w.plan_id = p_plan), '{}'::jsonb) as wk,
             (select min(w.week_start) from public.lookahead_weeks w where w.plan_id = p_plan and w.week_end >= greatest(x.s, v_start)) as first_ws
      from public.lookahead_items i
      cross join lateral (select coalesce(i.planned_start, v_start) as s,
                                 greatest(coalesce(i.planned_finish, i.planned_start, v_start), coalesce(i.planned_start, v_start)) as f,
                                 least(greatest(coalesce(i.pct_complete, 0), 0), 100) as pct) x
      where i.plan_id = p_plan and i.status = 'active' and i.schedule_task_id is not null and not i.is_milestone
    ),
    links as (
      select it.id as item_id, it.schedule_task_id as task_id, l.element_id
      from it join public.task_element_links l on l.task_id = it.schedule_task_id
      where (to_jsonb(l) ->> 'deleted_at') is null
    ),
    rows_direct as (
      select lk.item_id, t.element_id, t.material_spec_id, t.planned_qty * (1 + ms.wastage_pct / 100) as need, 1::numeric as share
      from links lk
      join public.element_takeoffs t on t.element_id = lk.element_id and t.deleted_at is null
        -- a take-off tagged with a BoQ item belongs to the tasks delivering that item, not to every task on the element
        -- (drilling / rebar / concrete tasks of one pile group must not each carry its whole rebar take-off)
        and (t.boq_item_id is null
             or not exists (select 1 from public.task_boq_links b0 where b0.task_id = lk.task_id and (to_jsonb(b0) ->> 'deleted_at') is null)
             or exists (select 1 from public.task_boq_links b1 where b1.task_id = lk.task_id and b1.boq_item_id = t.boq_item_id
                          and (to_jsonb(b1) ->> 'deleted_at') is null))
      join public.material_specs ms on ms.id = t.material_spec_id
    ),
    rows_boq as (
      select it.id as item_id, t.element_id, t.material_spec_id, t.planned_qty * (1 + ms.wastage_pct / 100) as need, sh.share
      from it
      join public.task_boq_links b on b.task_id = it.schedule_task_id and (to_jsonb(b) ->> 'deleted_at') is null
      join public.boq_items bq on bq.id = b.boq_item_id
      -- qty_share = BoQ quantity (item unit) delivered by this task → share of the item's take-off.
      cross join lateral (select coalesce((to_jsonb(b) ->> 'qty_share')::numeric, (to_jsonb(b) ->> 'planned_qty')::numeric) as raw) r0
      cross join lateral (select case when r0.raw is null or bq.quantity <= 0 then 1
                                      else least(greatest(r0.raw, 0) / bq.quantity, 1) end as share) sh
      join public.element_takeoffs t on t.boq_item_id = b.boq_item_id and t.deleted_at is null and t.project_id = v_project
      join public.material_specs ms on ms.id = t.material_spec_id
      where not exists (select 1 from links lk where lk.item_id = it.id and lk.element_id = t.element_id)
    ),
    rws as (select * from rows_direct union all select * from rows_boq),
    agg as (
      select rw.item_id, rw.material_spec_id, array_agg(distinct rw.element_id) as els,
             sum(rw.need * rw.share) as total_need,
             sum(greatest(rw.need * rw.share - greatest(rw.need * rw.share * it.pct / 100, coalesce(iss.qty, 0) * rw.share), 0)) as remaining
      from rws rw
      join it on it.id = rw.item_id
      left join lateral (select -sum(sl.qty) as qty from public.stock_ledger sl
                         where sl.element_id = rw.element_id and sl.material_spec_id = rw.material_spec_id
                           and sl.doc_type in ('miv','mrn')) iss on true
      group by rw.item_id, rw.material_spec_id
    )
    select a.item_id, a.material_spec_id, a.els, a.total_need, a.remaining, it.s, it.f, it.den, it.num, it.wk, it.first_ws,
           it.sort_key, ms.lead_time_days, ms.safety_days, ms.pack_size
    from agg a join it on it.id = a.item_id join public.material_specs ms on ms.id = a.material_spec_id
    where a.remaining > 0.0005
    order by a.material_spec_id, greatest(it.s, v_start), it.sort_key, a.item_id
  loop
    v_share := case when d.den > 0 then least(d.num / d.den, 1) else 1 end;
    if round(d.remaining * v_share, 3) <= 0.0005 then continue; end if;

    if v_spec is distinct from d.material_spec_id then
      v_spec := d.material_spec_id;
      select coalesce(sum(sl.qty), 0) into v_ati from public.stock_ledger sl
        where sl.project_id = v_project and sl.material_spec_id = v_spec and sl.stock_status = 'available';
      v_ati := greatest(v_ati - coalesce((
        select sum(greatest(coalesce(ml.approved_qty, 0) - coalesce(x.issued, 0), 0))
        from public.mr_lines ml join public.material_requests mr on mr.id = ml.mr_id
        left join lateral (select sum(vl.qty) as issued from public.miv_lines vl
                           join public.mivs mv on mv.id = vl.miv_id and mv.status <> 'reversed' where vl.mr_line_id = ml.id) x on true
        where mr.project_id = v_project and ml.material_spec_id = v_spec and ml.deleted_at is null
          and app.la_mr_kind(mr) = 'site_use' and mr.status::text in ('approved','sourced','ordered','partially_issued')
          and (ml.lookahead_item_id is null or not (ml.lookahead_item_id = any (v_items)))), 0), 0);
      select coalesce(array_agg(ps.expected_date order by ps.expected_date nulls last, ps.po_number), '{}'),
             coalesce(array_agg(ps.outstanding_qty order by ps.expected_date nulls last, ps.po_number), '{}'),
             coalesce(array_agg(ps.po_number::text order by ps.expected_date nulls last, ps.po_number), '{}')
        into v_po_eta, v_po_qty, v_po_no
        from public.v_po_line_status ps
        where ps.project_id = v_project and ps.material_spec_id = v_spec
          and ps.po_status in ('approved','sent','partially_received') and ps.outstanding_qty > 0;
      select coalesce(sum(greatest(coalesce(ml.approved_qty, ml.qty) - coalesce(pp.ordered_qty, 0), 0)), 0) into v_proc
        from public.mr_lines ml join public.material_requests mr on mr.id = ml.mr_id
        left join public.v_mr_line_procurement pp on pp.mr_line_id = ml.id
        where mr.project_id = v_project and ml.material_spec_id = v_spec and ml.deleted_at is null
          and app.la_mr_kind(mr) = 'purchase'
          and mr.status::text in ('approved','approved_by_management','with_procurement','sourced');
      select coalesce(sum(ml.qty), 0) into v_pend
        from public.mr_lines ml join public.material_requests mr on mr.id = ml.mr_id
        where mr.project_id = v_project and ml.material_spec_id = v_spec and ml.deleted_at is null
          and app.la_mr_kind(mr) = 'purchase'
          and mr.status::text in ('draft','submitted','reviewed','reviewed_by_coordinator','returned')
          and (mr.status::text <> 'draft' or mr.lookahead_plan_id = p_plan or ml.lookahead_item_id = any (v_items));
      select coalesce(array_agg(distinct mr.number), '{}') into v_mrs
        from public.mr_lines ml join public.material_requests mr on mr.id = ml.mr_id
        where mr.project_id = v_project and ml.material_spec_id = v_spec and ml.deleted_at is null
          and app.la_mr_kind(mr) = 'purchase'
          and mr.status::text in ('draft','submitted','reviewed','reviewed_by_coordinator','returned',
                                  'approved','approved_by_management','with_procurement','sourced')
          and (mr.status::text <> 'draft' or mr.lookahead_plan_id = p_plan or ml.lookahead_item_id = any (v_items));
    end if;

    r := null;
    r.plan_id := p_plan; r.project_id := v_project; r.item_id := d.item_id; r.material_spec_id := d.material_spec_id;
    r.element_ids := d.els;
    r.total_need := round(d.total_need, 3);
    r.remaining := round(d.remaining, 3);
    r.window_need := round(d.remaining * v_share, 3);
    r.lead_time_days := d.lead_time_days; r.safety_days := d.safety_days; r.pack_size := d.pack_size;
    r.need_by := app.la_shift(v_project, greatest(d.s, v_start), -d.safety_days);
    r.order_by := app.la_shift(v_project, r.need_by, -d.lead_time_days);
    if d.den > 0 then
      select coalesce(jsonb_object_agg(e.key, round(d.remaining * e.value::numeric / d.den, 3)) filter (where e.value::numeric > 0), '{}'::jsonb)
        into r.weekly_need from jsonb_each_text(d.wk) e;
    else
      r.weekly_need := case when d.first_ws is not null then jsonb_build_object(d.first_ws::text, r.window_need) else '{}'::jsonb end;
    end if;

    -- allocation
    v_rem := r.window_need;
    r.ati_before := round(v_ati, 3);
    r.from_stock := least(v_rem, v_ati); v_ati := v_ati - r.from_stock; v_rem := v_rem - r.from_stock;
    r.from_po := 0; r.from_po_late := 0; v_pos := '{}';
    for k in 1 .. coalesce(array_length(v_po_eta, 1), 0) loop
      exit when v_rem <= 0.0005;
      if v_po_qty[k] > 0.0005 and v_po_eta[k] is not null and v_po_eta[k] <= r.need_by then
        v_take := least(v_rem, v_po_qty[k]);
        v_po_qty[k] := v_po_qty[k] - v_take; v_rem := v_rem - v_take; r.from_po := r.from_po + v_take;
        v_pos := v_pos || v_po_no[k];
        r.next_po_eta := coalesce(r.next_po_eta, v_po_eta[k]);
      end if;
    end loop;
    r.short_firm := round(greatest(v_rem, 0), 3);
    for k in 1 .. coalesce(array_length(v_po_eta, 1), 0) loop
      exit when v_rem <= 0.0005;
      if v_po_qty[k] > 0.0005 then
        v_take := least(v_rem, v_po_qty[k]);
        v_po_qty[k] := v_po_qty[k] - v_take; v_rem := v_rem - v_take; r.from_po_late := r.from_po_late + v_take;
        v_pos := v_pos || v_po_no[k];
        r.late_po_eta := coalesce(r.late_po_eta, v_po_eta[k]);
      end if;
    end loop;
    r.from_procurement := least(greatest(v_rem, 0), v_proc); v_proc := v_proc - r.from_procurement; v_rem := v_rem - r.from_procurement;
    r.from_pending_pr := least(greatest(v_rem, 0), v_pend); v_pend := v_pend - r.from_pending_pr; v_rem := v_rem - r.from_pending_pr;
    r.from_stock := round(r.from_stock, 3); r.from_po := round(r.from_po, 3); r.from_po_late := round(r.from_po_late, 3);
    r.from_procurement := round(r.from_procurement, 3); r.from_pending_pr := round(r.from_pending_pr, 3);
    r.to_order := round(greatest(v_rem, 0), 3);
    r.suggested_qty := case when r.to_order > 0.0005 then ceil(r.to_order / r.pack_size) * r.pack_size else 0 end;
    r.raise_pr_now := r.to_order > 0.0005 and r.order_by <= v_today + 7;
    r.late_order := r.to_order > 0.0005 and r.order_by < v_today;
    r.arrives_late := r.from_po_late > 0.0005;
    r.suggest_sur := r.from_stock > 0.0005 and r.need_by <= v_today + 14;
    r.po_numbers := (select coalesce(array_agg(distinct x), '{}') from unnest(v_pos) x);
    r.mr_numbers := case when r.from_procurement + r.from_pending_pr > 0 then v_mrs else '{}' end;
    return next r;
  end loop;
end $$;

create or replace function public.create_sur_from_lookahead(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p);
  i public.lookahead_items;
  pl public.lookahead_plans;
  w public.lookahead_weeks;
  v_today date := app.la_today();
  v_store uuid;
  v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid());
  v_number text;
  v_mr_lines jsonb := '[]'::jsonb;
  v_els jsonb;
  l record;
  e record;
  v_qty numeric; v_left numeric; v_part numeric; v_tot numeric; v_n int; v_k int;
  v_req date;
  v_block uuid;
  v_res jsonb;
begin
  if v_seen is not null then return v_seen; end if;
  select * into i from public.lookahead_items where id = (p ->> 'item_id')::uuid;
  if not found then raise exception 'Look-ahead item not found'; end if;
  select * into pl from public.lookahead_plans where id = i.plan_id;
  perform app.require_member(i.project_id);
  perform app.require_role('site_engineer','office_engineer','coordinator','admin');
  if pl.status = 'closed' then raise exception 'Look-ahead % is closed', pl.period_label; end if;
  if app.has_role('site_engineer') and i.responsible_id is not null and i.responsible_id <> auth.uid() then
    raise exception 'Only the responsible site engineer can request materials for "%"', i.name;
  end if;
  if p ->> 'week_id' is not null then
    select * into w from public.lookahead_weeks where id = (p ->> 'week_id')::uuid and plan_id = pl.id;
    if not found then raise exception 'Week not found in this look-ahead'; end if;
  end if;
  v_store := coalesce((p ->> 'store_id')::uuid,
    (select id from public.stores where project_id = i.project_id and deleted_at is null order by (store_type = 'main') desc, created_at limit 1));
  perform app.require_store(i.project_id, v_store);

  for l in
    select c.material_spec_id as spec, c.need_by, c.element_ids, c.from_stock,
           case when w.id is not null then coalesce((c.weekly_need ->> w.week_start::text)::numeric, 0) else c.window_need end as need,
           (x ->> 'qty')::numeric as asked
    from app.la_material_calc(pl.id) c
    left join jsonb_array_elements(coalesce(p -> 'lines', '[]'::jsonb)) x on (x ->> 'material_spec_id')::uuid = c.material_spec_id
    where c.item_id = i.id
      and (jsonb_array_length(coalesce(p -> 'lines', '[]'::jsonb)) = 0 or x is not null)
  loop
    v_qty := round(coalesce(l.asked, least(l.need, l.from_stock)), 3);
    if v_qty <= 0 then continue; end if;
    v_req := least(coalesce(v_req, l.need_by), l.need_by);
    -- element split proportional to the elements' take-off of this spec
    select coalesce(sum(t.planned_qty), 0), count(*) into v_tot, v_n from public.element_takeoffs t
      where t.element_id = any (l.element_ids) and t.material_spec_id = l.spec and t.deleted_at is null;
    v_els := '[]'::jsonb; v_left := v_qty; v_k := 0;
    for e in select t.element_id, t.planned_qty from public.element_takeoffs t
             where t.element_id = any (l.element_ids) and t.material_spec_id = l.spec and t.deleted_at is null
             order by t.planned_qty desc, t.element_id loop
      v_k := v_k + 1;
      v_part := case when v_k = v_n then v_left else round(v_qty * e.planned_qty / nullif(v_tot, 0), 3) end;
      if v_part > 0 then
        v_els := v_els || jsonb_build_object('id', gen_random_uuid(), 'element_id', e.element_id, 'qty', v_part);
        v_left := v_left - v_part;
      end if;
    end loop;
    v_mr_lines := v_mr_lines || jsonb_build_object('id', gen_random_uuid(), 'material_spec_id', l.spec, 'qty', v_qty,
      'required_date', greatest(l.need_by, v_today), 'lookahead_item_id', i.id, 'elements', v_els,
      'remarks', 'Look-ahead ' || pl.period_label || ': ' || i.name);
  end loop;
  if jsonb_array_length(v_mr_lines) = 0 then
    raise exception 'Nothing in stock to request for "%" (order it with a purchase request first)', i.name;
  end if;

  -- block: the item's element, else an element linked to the task or used on the lines, else the task's block,
  -- else the project's only block (site-use requests need one; schedule-driven items often carry none)
  v_block := coalesce(
    (select el.block_id from public.elements el where el.id = i.element_id),
    (select el.block_id from public.task_element_links tl join public.elements el on el.id = tl.element_id
      where tl.task_id = i.schedule_task_id and (to_jsonb(tl) ->> 'deleted_at') is null and el.block_id is not null
      order by el.block_id limit 1),
    (select el.block_id from jsonb_array_elements(v_mr_lines) ln, jsonb_array_elements(ln -> 'elements') x
      join public.elements el on el.id = (x ->> 'element_id')::uuid where el.block_id is not null limit 1),
    (select t.block_id from public.schedule_tasks t where t.id = i.schedule_task_id),
    (select min(b.id::text)::uuid from public.blocks b where b.project_id = i.project_id
      and (to_jsonb(b) ->> 'deleted_at') is null having count(*) = 1));
  v_number := coalesce(nullif(p ->> 'number', ''), app.la_doc_number(i.project_id, 'SR', pl.period_start));
  v_res := public.save_mr(jsonb_build_object('id', v_id, 'project_id', i.project_id, 'number', v_number,
    'request_type', 'site_use', 'block_id', coalesce((p ->> 'block_id')::uuid, v_block), 'priority', 'normal',
    'required_date', coalesce((p ->> 'required_date')::date, greatest(coalesce(v_req, v_today), v_today)),
    'delivery_location', (select name from public.stores where id = v_store), 'store_id', v_store,
    'purpose', 'Look-ahead site use: ' || i.name, 'is_lookahead', true, 'lookahead_plan_id', pl.id,
    'submit', coalesce((p ->> 'submit')::boolean, false), 'lines', v_mr_lines));
  update public.material_requests set lookahead_plan_id = pl.id, is_lookahead = true where id = v_id and lookahead_plan_id is distinct from pl.id;
  update public.mr_lines set lookahead_item_id = i.id where mr_id = v_id and lookahead_item_id is distinct from i.id;
  return app.op_done(p, 'create_sur_from_lookahead', jsonb_build_object('ok', true, 'id', v_id, 'number', v_number,
    'status', v_res ->> 'status', 'lines', v_mr_lines));
end $$;


-- >>>>>>>>>>>>>>>>>>>> 20261102000023_e2e_progress_fixes.sql

-- =============================================================================
-- Progress workflow fixes found in the end-to-end test (TWR, real .mpp schedule).
--
-- 1. Rejected / adjusted reports left the "reported" figures on the task (schedule_tasks.reported_pct,
--    task_boq_links.reported_qty, task_steps.reported_pct) at the refused value. Daily output adds today's
--    quantity to the reported figure, so after a rejection (or a measurement cut from 450 to 420 m2) the next
--    day's output built on the refused quantity. Now, whenever a report is rejected or adjusted, the reported
--    figures are reset to the latest report that still stands (its verified figure when verified/adjusted),
--    or to the verified figures when no report stands.
-- =============================================================================

create or replace function app.resync_reported(p_task uuid) returns void
language plpgsql security definer set search_path = public as $$
declare r public.task_progress;
begin
  select * into r from public.task_progress
   where task_id = p_task and status <> 'rejected'
   order by created_at desc limit 1;
  if not found then
    update public.schedule_tasks set reported_pct = pct_complete where id = p_task;
    update public.task_boq_links set reported_qty = verified_qty where task_id = p_task and deleted_at is null;
    update public.task_steps set reported_pct = verified_pct where task_id = p_task;
    return;
  end if;
  update public.schedule_tasks
     set reported_pct = coalesce(case when r.status in ('verified','adjusted') then r.verified_pct end, r.pct_complete, reported_pct)
   where id = p_task;
  update public.task_boq_links l set reported_qty = y.qty_to_date
    from jsonb_to_recordset(coalesce(case when r.status in ('verified','adjusted') then r.verified_qty end, r.qty, '[]'::jsonb))
         as y(boq_item_id uuid, qty_to_date numeric)
   where l.task_id = p_task and l.boq_item_id = y.boq_item_id and l.deleted_at is null;
  update public.task_steps s set reported_pct = y.done_pct
    from jsonb_to_recordset(coalesce(case when r.status in ('verified','adjusted') then r.verified_steps end, r.steps, '[]'::jsonb))
         as y(step_id uuid, done_pct numeric)
   where s.task_id = p_task and s.id = y.step_id;
end $$;
revoke execute on function app.resync_reported(uuid) from public;

create or replace function app.trg_task_progress_resync() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.status = 'reported' and new.status in ('rejected', 'adjusted') then
    perform app.resync_reported(new.task_id);
  end if;
  return null;
end $$;

drop trigger if exists resync_reported on public.task_progress;
create trigger resync_reported after update of status on public.task_progress
  for each row execute function app.trg_task_progress_resync();

-- =============================================================================
-- 2. Daily output labour hours did not reach cost control: the hours were stored on the diary line only, so
--    "Estimate from site diary hours" (estimate_costs_from_usage, which reads resource_usage) found nothing and
--    task-level CPI had no actual cost from the site. Each daily output with labour hours now also records the
--    labour usage (man-hours on the task, linked to the diary; id = the diary line id, so it is written once),
--    and existing outputs are back-filled.
-- =============================================================================
create or replace function app.trg_diary_activity_usage() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if coalesce(new.labour_hours, 0) > 0 then
    insert into public.resource_usage (id, project_id, usage_date, kind, task_id, boq_item_id, qty, uom, diary_id, remarks, created_by)
    values (new.id, new.project_id, new.activity_date, 'labour', new.task_id,
      (select case when count(*) = 1 then min(l.boq_item_id::text)::uuid end from public.task_boq_links l
        where l.task_id = new.task_id and l.deleted_at is null),
      new.labour_hours, 'man-hour', new.diary_id,
      'Daily output' || coalesce(' — ' || new.headcount || ' people', '') || coalesce(' · ' || new.remarks, ''), new.created_by)
    on conflict (id) do nothing;
  end if;
  return null;
end $$;

drop trigger if exists labour_usage on public.diary_activities;
create trigger labour_usage after insert on public.diary_activities
  for each row execute function app.trg_diary_activity_usage();

insert into public.resource_usage (id, project_id, usage_date, kind, task_id, boq_item_id, qty, uom, diary_id, remarks, created_by)
select a.id, a.project_id, a.activity_date, 'labour', a.task_id,
       (select case when count(*) = 1 then min(l.boq_item_id::text)::uuid end from public.task_boq_links l
         where l.task_id = a.task_id and l.deleted_at is null),
       a.labour_hours, 'man-hour', a.diary_id,
       'Daily output' || coalesce(' — ' || a.headcount || ' people', '') || coalesce(' · ' || a.remarks, ''), a.created_by
  from public.diary_activities a
 where coalesce(a.labour_hours, 0) > 0 and a.deleted_at is null
on conflict (id) do nothing;


-- Make the API see the new table straight away.
notify pgrst, 'reload schema';
